# Salva il record del punteggio in un file JSON nella cartella utente
func save_high_score(high_score: int) -> void:
	var save_data: Dictionary = {
		"high_score": high_score
	}
	var json_string: String = JSON.stringify(save_data)
	var file: FileAccess = FileAccess.open("user://savegame.json", FileAccess.WRITE)
	if file == null:
		print("Impossibile aprire il file per la scrittura.")
		return
	file.store_string(json_string)

# Carica il record dal file in modo sicuro
func load_high_score() -> int:
	if not FileAccess.file_exists("user://savegame.json"):
		return 0

	var file: FileAccess = FileAccess.open("user://savegame.json", FileAccess.READ)
	if file == null:
		return 0

	var content: String = file.get_as_text()
	var json: JSON = JSON.new()
	var parse_result: Error = json.parse(content)

	if parse_result != OK:
		print("Errore di lettura JSON o file danneggiato.")
		return 0

	if json.data is Dictionary and json.data.has("high_score"):
		return int(json.data["high_score"])

	return 0
